#include <algorithm>
#include <iostream>
#include "Simulation.hpp"
Simulation::Simulation(Grid&g,std::uint32_t s):window(sf::VideoMode(Config::WindowWidth,Config::WindowHeight),"Ant Colony Simulation"),grid(g),seed(s){window.setFramerateLimit(Config::FrameRate);}
void Simulation::restart(){grid.reset(seed);paused=false;}
void Simulation::handleMouse(const sf::Event&e){if(e.type!=sf::Event::MouseButtonPressed&&e.type!=sf::Event::MouseMoved)return;sf::Vector2i p=sf::Mouse::getPosition(window);if(!renderer.isInsideWorld(p))return;Coordinates c=renderer.pixelToCell(p);if(e.type==sf::Event::MouseButtonPressed){if(e.mouseButton.button==sf::Mouse::Left)grid.addSugarAt(c,Config::SugarPerSource);else if(e.mouseButton.button==sf::Mouse::Right)grid.removeSugarAt(c,Config::SugarPerSource);}else if(e.type==sf::Event::MouseMoved&&sf::Mouse::isButtonPressed(sf::Mouse::Left))grid.addSugarAt(c,Config::SugarPerSource);else if(e.type==sf::Event::MouseMoved&&sf::Mouse::isButtonPressed(sf::Mouse::Right))grid.removeSugarAt(c,Config::SugarPerSource);if(debugCell){grid.inspectCell(c,debugText);}}
void Simulation::handleEvents(){sf::Event e{};while(window.pollEvent(e)){if(e.type==sf::Event::Closed){window.close();continue;}if(e.type==sf::Event::MouseButtonPressed){handleMouse(e);continue;}if(e.type==sf::Event::MouseMoved){handleMouse(e);continue;}if(e.type!=sf::Event::KeyPressed)continue;switch(e.key.code){case sf::Keyboard::Escape:window.close();break;case sf::Keyboard::Space:paused=!paused;break;case sf::Keyboard::P:showPheromones=!showPheromones;break;case sf::Keyboard::A:showAnts=!showAnts;break;case sf::Keyboard::S:showSugar=!showSugar;break;case sf::Keyboard::N:showNests=!showNests;break;case sf::Keyboard::I:showStats=!showStats;break;case sf::Keyboard::T:break;case sf::Keyboard::G:showGraph=!showGraph;break;case sf::Keyboard::D:debugCell=!debugCell;break;case sf::Keyboard::H:showHelp=!showHelp;break;case sf::Keyboard::R:restart();break;case sf::Keyboard::E:grid.exportStatsCsv("simulation_stats.csv");break;case sf::Keyboard::Add:case sf::Keyboard::Equal:simulationStepsPerSecond=std::min(480.,simulationStepsPerSecond*1.25);break;case sf::Keyboard::Subtract:case sf::Keyboard::Hyphen:simulationStepsPerSecond=std::max(1.,simulationStepsPerSecond/1.25);break;default:break;}}}
void Simulation::run(){sf::Clock clock;double acc=0;while(window.isOpen()){handleEvents();float dt=clock.restart().asSeconds();acc+=dt;double fixed=1./simulationStepsPerSecond;int n=0;while(!paused&&acc>=fixed&&n<Config::MaxSimulationStepsPerFrame){grid.update();acc-=fixed;++n;}window.clear(sf::Color::Black);renderer.draw(window,grid,showPheromones,showAnts,showSugar,showNests,showStats,showTerritory,showGraph,debugCell,showHelp,debugText);window.display();}}
